{
	"@context": "https://schema.org",
	"@type": "TechArticle",
	"headline": "CSS Pagination Component, No JavaScript | Pure CSS",
	"description": "Numbered page buttons with an active state driven by radio inputs and :checked.",
	"url": "https://purecss.com/examples/pagination/",
	"author": {
		"@type": "Person",
		"name": "Adam Culpepper",
		"url": "https://x.com/adamculpepper"
	},
	"publisher": {
		"@type": "Organization",
		"name": "Pure CSS",
		"url": "https://purecss.com"
	},
	"datePublished": "2026-06-07","dateModified": "2026-08-29"
}

{
	"@context": "https://schema.org",
	"@type": "FAQPage",
	"mainEntity": [{
		"@type": "Question",
		"name": "How do I build pagination with CSS only?",
		"acceptedAnswer": { "@type": "Answer", "text": "One hidden radio per page, all sharing a `name`, placed before the bar and the content. A `` per page points at its radio, and a rule per page highlights the label and shows the matching content block through the `~` combinator. The first radio carries `checked` so the component has a starting state." }
	},{
		"@type": "Question",
		"name": "Can CSS pagination have working prev and next buttons?",
		"acceptedAnswer": { "@type": "Answer", "text": "Yes, but not by arithmetic. CSS cannot step from the current page to the next one, so you include a prev and a next button for every position and reveal only the pair that matches the checked radio. The variant on this page does exactly that for four pages." }
	},{
		"@type": "Question",
		"name": "Is CSS-only pagination bad for SEO?",
		"acceptedAnswer": { "@type": "Answer", "text": "For paginating real content, yes. Everything lives on one URL, so there is nothing for a crawler to follow and nothing for anyone to link to. Use ordinary links to real pages and style them with the same CSS. Keep the radio version for content that is already in the document." }
	},{
		"@type": "Question",
		"name": "How do I mark the current page for a screen reader?",
		"acceptedAnswer": { "@type": "Answer", "text": "`aria-current=&#92;&quot;page&#92;&quot;` on the element representing the active page, inside a `` with an accessible name such as `aria-label=&#92;&quot;Pagination&#92;&quot;`. The color change is for sighted readers only and carries nothing on its own." }
	},{
		"@type": "Question",
		"name": "How many pages is this technique good for?",
		"acceptedAnswer": { "@type": "Answer", "text": "Up to about ten before the selector lists get unwieldy, and fewer than that if you want working prev and next, since those add two rules and two hidden buttons per page. Past that point, generate the stylesheet or move the state out of CSS." }
	}]
}

